import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.logging.Logger;

public class UserProfileServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(UserProfileServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String userId = req.getParameter("id");
        String fields = req.getParameter("fields");

        // Basic null check
        if (userId == null || userId.isEmpty()) {
            resp.sendError(400, "Missing id parameter");
            return;
        }

        // Validate userId is numeric
        if (!userId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid user ID format");
            return;
        }

        // Fields parameter allows selecting which columns to return
        // Default to safe set if not specified
        String columns = "username, email, created_at";
        if (fields != null && !fields.isEmpty()) {
            // Allow only alphanumeric and commas - but this regex has a flaw
            // It checks each character but doesn't prevent SQL keywords
            if (fields.matches("^[a-zA-Z0-9_,\\s]+$")) {
                columns = fields;
            } else {
                resp.sendError(400, "Invalid fields parameter");
                return;
            }
        }

        String query = "SELECT " + columns + " FROM user_profiles WHERE user_id = " + userId;
        log.info("Executing query for user: " + userId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("{\"results\":[");
            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",");
                json.append("{");
                for (int i = 1; i <= colCount; i++) {
                    if (i > 1) json.append(",");
                    json.append("\"").append(meta.getColumnName(i)).append("\":");
                    json.append("\"").append(rs.getString(i)).append("\"");
                }
                json.append("}");
                first = false;
            }
            json.append("]}");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.warning("Database error: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String userId = req.getParameter("id");
        String bio = req.getParameter("bio");
        String website = req.getParameter("website");

        if (userId == null || !userId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid user ID");
            return;
        }

        // Use PreparedStatement for updates (safe)
        String update = "UPDATE user_profiles SET bio = ?, website = ? WHERE user_id = ?";
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement pstmt = conn.prepareStatement(update)) {
            pstmt.setString(1, bio);
            pstmt.setString(2, website);
            pstmt.setInt(3, Integer.parseInt(userId));
            int rows = pstmt.executeUpdate();
            resp.getWriter().write("{\"updated\":" + rows + "}");
        } catch (SQLException e) {
            log.warning("Update error: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        }
    }
}
